// 如果是前端调用，确保 permission_id 是有效的 UUID
const isValidUUID = (id) => {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id);
};

// 调用 API 前验证
if (!isValidUUID(permission_id)) {
  alert("请提供有效的 UUID 格式的 permission_id");
  return;
}

from fastapi import Query, HTTPException
from uuid import UUID
from typing import Optional

@app.get("/api/v1/tenants")
async def get_tenants(
    permission_id: Optional[str] = Query(None, description="权限ID (UUID格式)")
):
    if permission_id:
        try:
            # 尝试转换为 UUID，自动验证格式
            UUID(permission_id)
        except ValueError:
            raise HTTPException(
                status_code=400,
                detail="permission_id 必须是有效的 UUID 格式，例如 '123e4567-e89b-12d3-a456-426614174000'"
            )

